import pandas as pd, numpy as np, glob, os
from scipy.stats import spearmanr
files=glob.glob('../persistent/index_data/*.csv')
trad=['000300.SH','SPX','HSI','N225','SX5E','000688.SH','SOX','NDX','XAU','COPPER','WTI','BTC','ETH','US10Y','CN10Y']
frames={}
for s in trad:
 p='../persistent/index_data/'+s+'.csv'
 if os.path.exists(p):
  d=pd.read_csv(p); d['date']=pd.to_datetime(d.date); frames[s]=d.set_index('date').close
px=pd.DataFrame(frames).sort_index(); ret=px.pct_change()
r5=px/px.shift(5)-1
# relative short-term reversal: underperformers vs peer median are favored
fac=-(r5.sub(r5.median(axis=1),axis=0))
fwd=px.shift(-1)/px-1
ics=[]; dates=[]; nobs=[]
for dt in fac.index:
 x=fac.loc[dt]; y=fwd.loc[dt]; z=pd.concat([x,y],axis=1).dropna()
 if len(z)>=8:
  v=spearmanr(z.iloc[:,0],z.iloc[:,1]).statistic
  if np.isfinite(v): ics.append(v); dates.append(dt); nobs.append(len(z))
a=np.array(ics); print('factor relative_5d_reversal dates',len(a),'avg_names',np.mean(nobs),'coverage',np.isfinite(fac).sum().sum()/fac.size)
print('IC',a.mean(),'ICIR',a.mean()/a.std(ddof=1),'hit',np.mean(a>0),'turnover',np.mean((fac.rank(axis=1,pct=True)-fac.rank(axis=1,pct=True).shift(1)).abs().mean(axis=1).dropna()))
for lo,hi in [('2020','2022'),('2023','2024'),('2025','2026')]:
 q=a[(np.array(dates)>=pd.Timestamp(lo))&(np.array(dates)<=pd.Timestamp(hi))]; print(lo,hi,len(q),q.mean() if len(q) else np.nan,q.mean()/q.std(ddof=1) if len(q)>1 else np.nan)
for h in [3,5,10]:
 yy=px.shift(-h)/px-1; vv=[]
 for dt in fac.index:
  z=pd.concat([fac.loc[dt],yy.loc[dt]],axis=1).dropna()
  if len(z)>=8: vv.append(spearmanr(z.iloc[:,0],z.iloc[:,1]).statistic)
 v=np.array(vv); print('h',h,'IC',v.mean(),'ICIR',v.mean()/v.std(ddof=1), 'dates',len(v))

