 q=pd.DataFrame({'date':d.index,'factor':f,'y1':d.c.shift(-1)/d.c-1,'y5':d.c.shift(-5)/d.c-1,'y10':d.c.shift(-10)/d.c-1});rows.append(q.assign(symbol=s))
x=pd.concat(rows)
for h in [1,5,10]:
