import numpy as np, pandas as pd
from alphacrafter.sim.utils import get_index_daily_data
U=['000300.SH','SPX','HSI','N225','SX5E','000688.SH','SOX','NDX','XAU','COPPER','WTI','BTC','ETH','US10Y','CN10Y']
frames={}
for s in U:
 d=get_index_daily_data(s,2500)
 if d is not None and len(d)>100:
  d=d.copy(); d['date']=pd.to_datetime(d.date); d=d.set_index('date').sort_index(); frames[s]=d
# drawdown recovery / range position: position above 60d low, normalized by 60d range
rows=[]
for s,d in frames.items():
 c=d.close.astype(float); lo=c.rolling(60,min_periods=40).min(); hi=c.rolling(60,min_periods=40).max()
 # sigmoid-ish range position centered; avoid pure momentum by penalizing recent acceleration
 f=(c-lo)/(hi-lo).replace(0,np.nan)
 # distance from low relative to realized vol, smooth 5d
 f=f.ewm(span=5,min_periods=5).mean()
 fr=c.shift(-1)/c-1
 for dt in d.index:
  rows.append((dt,s,f.loc[dt],fr.loc[dt]))
x=pd.DataFrame(rows,columns=['date','sym','f','r']).dropna()
ics=[]; counts=[]
for dt,g in x.groupby('date'):
 if len(g)>=8 and g.f.nunique()>1 and g.r.nunique()>1:
  ics.append(g.f.corr(g.r,method='spearman')); counts.append(len(g))
ics=pd.Series(ics).dropna(); print('dates',len(ics),'avg_n',np.mean(counts),'IC',ics.mean(),'ICIR',ics.mean()/ics.std(ddof=1),'hit',np.mean(ics>0),'coverage',len(x)/sum(len(d) for d in frames.values()))
# 5 and 10 day decay
for h in [5,10]:
 z=[]
 for s,d in frames.items():
  c=d.close.astype(float); lo=c.rolling(60,min_periods=40).min(); hi=c.rolling(60,min_periods=40).max(); f=((c-lo)/(hi-lo).replace(0,np.nan)).ewm(span=5,min_periods=5).mean(); r=c.shift(-h)/c-1
  z.append(pd.DataFrame({'f':f,'r':r,'date':d.index}))
 z=pd.concat(z)
 q=[]
 for dt,g in z.groupby('date'):
  g=g.dropna()
  if len(g)>=8 and g.f.nunique()>1:q.append(g.f.corr(g.r,method='spearman'))
 q=pd.Series(q).dropna(); print(h,'dates',len(q),'IC',q.mean(),'ICIR',q.mean()/q.std(ddof=1))
# annual
x['year']=x.date.dt.year
for y,g in x.groupby('year'):
 q=[]
 for dt,a in g.groupby('date'):
  if len(a)>=8:q.append(a.f.corr(a.r,method='spearman'))
 q=pd.Series(q).dropna(); print(y,len(q),q.mean(),q.mean()/q.std(ddof=1))
# artifact
out=x.pivot(index='date',columns='sym',values='f'); out.to_csv('scripts/miner_2_20261217_recovery60_signal.csv')

