 c=d.close.astype(float); lo=c.rolling(60,min_periods=40).min(); hi=c.rolling(60,min_periods=40).max(); return ((c-lo)/(hi-lo).replace(0,np.nan)).ewm(span=5,min_periods=5).mean()
